1	export type ApiResult<T> = { ok: true; data: T } | { ok: false; error: string };
2	
3	export function unwrap<T>(result: ApiResult<T>): T {
4	  if (result.ok) {
5	    return result.data;
6	  }
7	}
8	
9	export async function getJson<T>(url: string): Promise<ApiResult<T>> {
10	  const res = await fetch(url);
11	  if (!res.ok) {
12	    return { ok: false, error: `HTTP ${res.status}` };
13	  }
14	  return { ok: true, data: (await res.json()) as T };
