Esse tem estado e eventos de clique — obrigatoriamente client component, então "use client" na primeira linha (esquecer isso é erro de build clássico do Next). Checklist: botões só-ícone precisam de aria-label; disabled nos limites com opacity+pointer-events; focus-visible:ring pros dois botões; número com tabular-nums pra não dançar de largura; aria-live no valor pra leitor de tela anunciar a mudança. O clamp vive numa função só, chamada pelos dois botões:
<tool_call>
{"name": "write_file", "arguments": {"path": "components/QuantityPicker.tsx", "content": ""use client";

import { useState } from "react";

type QuantityPickerProps = {
  min?: number;
  max?: number;
  initial?: number;
  onChange?: (value: number) => void;
};

export default function QuantityPicker({
  min = 1,
  max = 99,
  initial = 1,
  onChange,
}: QuantityPickerProps) {
  const [value, setValue] = useState(initial);

  function update(next: number) {
    const clamped = Math.max(min, Math.min(next, max));
    setValue(clamped);
    onChange?.(clamped);
  }

  const buttonClasses =
    "flex h-9 w-9 items-center justify-center rounded-xl border border-zinc-300 text-lg font-medium transition-colors hover:bg-zinc-100 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-zinc-500 disabled:pointer-events-none disabled:opacity-40 dark:border-zinc-700 dark:hover:bg-zinc-800";

  return (
    <div className="inline-flex items-center gap-3">
      <button
        type="button"
        onClick={() => update(value - 1)}
        disabled={value <= min}
        aria-label="Diminuir quantidade"
        className={buttonClasses}
      >
        −
      </button>
      <span className="w-8 text-center text-base font-semibold tabular-nums" aria-live="polite">
        {value}
      </span>
      <button
        type="button"
        onClick={() => update(value + 1)}
        disabled={value >= max}
        aria-label="Aumentar quantidade"
        className={buttonClasses}
      >
        +
      </button>
    </div>
  );
}
"}}
</tool_call>

